import { type Graph, type Label, plotSize, validate } from "./model.ts";
import { worksheetStyle, labeledTicks, piAxis, tickLabel } from "./appearance.ts";
import { decorate, decorated, paths } from "./geometry.ts";
import { parse, pgf } from "./expression.ts";
export const num = (x: number) => Number(x.toPrecision(12)).toString();
export function texLabel(l: Label): string {
  if (l.math) return `$${l.text}$`;
  const escapes: Record<string, string> = {
    "\\": "\\textbackslash{}",
    "{": "\\{",
    "}": "\\}",
    $: "\\$",
    "&": "\\&",
    "#": "\\#",
    _: "\\_",
    "%": "\\%",
    "~": "\\textasciitilde{}",
    "^": "\\textasciicircum{}",
  };
  return l.text
    .replace(/[\\{}$&#_%~^]/g, (c) => escapes[c])
    .replace(/[\r\n]/g, " ");
}
export function latex(graph: Graph): string {
  const g = validate(graph),
    s = g.settings,
    box = plotSize(g);
  const worksheet = worksheetStyle(g);
  const labelOptions = (which: "x" | "y") => {
    const values = labeledTicks(g, which);
    return [
      `  ${which}ticklabels={},`,
      `  extra ${which} ticks={${values.map(num).join(",")}},`,
      `  extra ${which} tick labels={${values.map((v) => `$${tickLabel(g, which, v).tex}$`).join(",")}},`,
      `  extra ${which} tick style={grid=none},`,
    ];
  };
  const lines = [
    "% Generated by Math Graph. Edit visually using metadata; manual edits here block regeneration.",
    s.angles === "degrees"
      ? "% Function angles are degrees, as in PGFPlots trigonometry."
      : "% Function angles are radians; deg(...) converts for PGFPlots trigonometry.",
    "% Explicit samples preserve preview discontinuity breaks. Narrow features may be missed.",
    worksheet
      ? "\\begin{tikzpicture}[baseline=(current bounding box.north)]"
      : "\\begin{tikzpicture}",
    // Fixed physical frame; labels may extend beyond it, as documented.
    `\\path[use as bounding box] (0,0) rectangle (${num(s.width)},${num(s.height)});`,
    "\\begin{axis}[",
    `  at={(${num((s.width - box.width) / 2)}cm,${num((s.height - box.height) / 2)}cm)}, anchor=south west,`,
    `  width=${num(box.width)}cm, height=${num(box.height)}cm, scale only axis,`,
    `  xmin=${num(s.xmin)}, xmax=${num(s.xmax)}, ymin=${num(s.ymin)}, ymax=${num(s.ymax)},`,
    `  xtick distance=${num(s.xtick)}, ytick distance=${num(s.ytick)},`,
    ...(worksheet
      ? [
          // Same axis options as the ap-calc and gr-10-adv notes; label placement is PGFPlots' middle-axis default.
          "  axis lines=middle, axis line style={very thick},",
          `  grid=${s.grid ? "major" : "none"}, grid style={thin,densely dotted,black!50},`,
          "  enlargelimits=false, clip=true,",
          ...labelOptions("x"),
          ...labelOptions("y"),
        ]
      : [
          `  axis lines=box, grid=${s.grid ? "major" : "none"}, clip=true,`,
          ...((s.tickLabels && s.tickLabels !== "all") ||
          piAxis(g, "x") ||
          piAxis(g, "y")
            ? [...labelOptions("x"), ...labelOptions("y")]
            : []),
        ]),
    `  xlabel={${texLabel(s.xlabel)}}, ylabel={${texLabel(s.ylabel)}},`,
    "  unbounded coords=jump, /pgf/number format/1000 sep={}",
    "]",
  ];
  const colour = (hex: string) => {
    const rgb = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
    return `{rgb,255:red,${rgb[0]};green,${rgb[1]};blue,${rgb[2]}}`;
  };
  const marker = (
    o: { color: string; width: number },
    x: number,
    y: number,
    open: boolean,
  ) =>
    `\\addplot[color=${colour(o.color)}, line width=${num(o.width)}pt, solid, only marks, mark=*, mark size=2.5pt, mark options={solid,fill=${open ? "white" : colour(o.color)}}] coordinates {(${num(x)},${num(y)})};`;
  // Endpoint circles go above every curve, like points, so open circles stay hollow.
  const endpoints: string[] = [];
  let pointsStarted = false;
  for (const o of [
    ...g.objects.filter((o) => o.type !== "point"),
    ...g.objects.filter((o) => o.type === "point"),
  ]) {
    if (o.type === "point" && !pointsStarted) {
      pointsStarted = true;
      lines.push(...endpoints);
    }
    if (!o.visible) continue;
    const opts = `color=${colour(o.color)}, line width=${num(o.width)}pt, ${o.dashed ? "dashed" : "solid"}`;
    if (o.type === "point") {
      lines.push(marker(o, o.x, o.y, o.open));
      if (o.label.text)
        lines.push(
          `\\node[anchor=south west,inner sep=4pt] at (axis cs:${num(o.x)},${num(o.y)}) {${texLabel(o.label)}};`,
        );
    } else if (decorated(o)) {
      const d = decorate(g, o);
      for (const piece of d.pieces) {
        const arrow =
          piece.arrowStart && piece.arrowEnd
            ? ", <->"
            : piece.arrowStart
              ? ", <-"
              : piece.arrowEnd
                ? ", ->"
                : "";
        if (o.type === "function")
          lines.push(
            `% y = ${o.expression.replace(/[\r\n]/g, " ")}`,
            `\\addplot[${opts}${arrow}, no marks, samples at={${piece.points.map((p) => num(p[0])).join(",")}}] {${pgf(parse(o.expression), s.angles === "degrees")}};`,
          );
        else
          lines.push(
            `\\addplot[${opts}${arrow}, no marks] coordinates {${piece.points.map((p) => `(${num(p[0])},${num(p[1])})`).join(" ")}};`,
          );
      }
      endpoints.push(...d.marks.map((m) => marker(o, m.x, m.y, m.open)));
    } else {
      for (const path of paths(g, o)) {
        if (o.type === "function") {
          // PGFPlots evaluates the same AST at precisely the preview's sample locations.
          lines.push(
            `% y = ${o.expression.replace(/[\r\n]/g, " ")}`,
            `\\addplot[${opts}, no marks, samples at={${path.map((p) => num(p[0])).join(",")}}] {${pgf(parse(o.expression), s.angles === "degrees")}};`,
          );
        } else
          lines.push(
            `\\addplot[${opts}, no marks] coordinates {${path.map((p) => `(${num(p[0])},${num(p[1])})`).join(" ")}};`,
          );
      }
    }
  }
  if (!pointsStarted) lines.push(...endpoints);
  lines.push("\\end{axis}", "\\end{tikzpicture}");
  return lines.join("\n") + "\n";
}
